package com.kanjimaster.service;

import com.kanjimaster.ai.SubtitleGenerator;
import com.kanjimaster.ai.youtube.YoutubeUrls;
import com.kanjimaster.dto.SubtitleWrapDto;
import com.kanjimaster.exception.BadRequestException;
import org.springframework.stereotype.Service;

/**
 * Subtitles for a YouTube video: served from the database when already processed, otherwise generated by the
 * active AI provider and stored (unless the provider is the stub).
 */
@Service
public class SubtitleService {
    private final VideoMetadataService videoMetadataService;
    private final SubtitleGenerator generator;

    public SubtitleService(VideoMetadataService videoMetadataService, SubtitleGenerator generator) {
        this.videoMetadataService = videoMetadataService;
        this.generator = generator;
    }

    public SubtitleWrapDto extract(String youtubeUrl) {
        String videoId = YoutubeUrls.extractVideoId(youtubeUrl)
                .orElseThrow(() -> new BadRequestException("Not a valid YouTube video URL"));

        SubtitleWrapDto subtitles = videoMetadataService.findByYoutubeId(videoId).orElseGet(() -> {
            SubtitleWrapDto generated = generator.generate(videoId);
            if (generator.isCacheable()) {
                videoMetadataService.createYoutubeVideo(generated, videoId);
            }
            return generated;
        });
        return subtitles.sorted();
    }
}
